// High-bit-depth (bd 8/10/12) differential test for HarborDeblockFrame.
// Mirrors deblock_frame_chroma_test.dart but packs planes at `bd` bits per
// pixel and drives the SW oracle with a matching `bitDepth`.

BigInt _packPlane(List<List<int>> pix, int w, int h, int bd) {
  final mask = (1 << bd) - 1;
  var v = BigInt.zero;
  for (var y = 0; y < h; y++) {
    for (var x = 0; x < w; x++) {
      v |= BigInt.from(pix[y][x] & mask) << ((y * w + x) * bd);
    }
  }
  return v;
}

BigInt _packMi(List<List<int>> g, int miRows, int miCols, int bits) {
  var v = BigInt.zero;
  for (var r = 0; r < miRows; r++) {
    for (var c = 0; c < miCols; c++) {
      v |= BigInt.from(g[r][c]) << ((r * miCols + c) * bits);
    }
  }
  return v;
}

List<List<int>> _fill(int r, int c, int val) =>
    List.generate(r, (_) => List.filled(c, val));

Future<void> runCase({
  required String label,
  required int bd,
  required int width,
  required int height,
  required int numPlanes,
  required int subX,
  required int subY,
  required List<List<int>> miTxY,
  required List<List<int>> miTxUV,
  required List<List<int>> lvlYv,
  required List<List<int>> lvlYh,
  required List<List<int>> lvlU,
  required List<List<int>> lvlV,
  required List<List<int>> skip,
  required List<List<int>> isInter,
  required List<List<int>> blockW,
  required List<List<int>> blockH,
  required int sharpness,
  required int iters,
  required int seed,
  required List<_Gold> gold,
  bool expectChange = true,
}) async {
  final miRows = height ~/ 4;
  final miCols = width ~/ 4;
  final cw = width >> subX;
  final ch = height >> subY;
  final s = bd - 8;
  final pxMax = (1 << bd) - 1;

  final dut = HarborDeblockFrame(
    width: width,
    height: height,
    numPlanes: numPlanes,
    subX: subX,
    subY: subY,
    bd: bd,
  );

  final drivers = <String, Logic>{};
  Logic drive(String port) {
    final w = dut.input(port).width;
    final sig = Logic(name: 'drv_$port', width: w);
    dut.input(port).srcConnection! <= sig;
    drivers[port] = sig;
    return sig;
  }

  for (final p in [
    'frame',
    'sharpness',
    'mi_tx_y',
    'mi_tx_uv',
    'mi_level_yv',
    'mi_level_yh',
    'mi_level_u',
    'mi_level_v',
    'mi_skip',
    'mi_is_inter',
    'mi_block_w',
    'mi_block_h',
  ]) {
    drive(p);
  }
  if (numPlanes == 3) {
    drive('frame_u');
    drive('frame_v');
  }

  final clk = SimpleClockGenerator(10).clk;
  await dut.build();
  Simulator.setMaxSimTime(200000000);
  unawaited(Simulator.run());

  drivers['sharpness']!.put(sharpness);
  drivers['mi_tx_y']!.put(_packMi(miTxY, miRows, miCols, 5));
  drivers['mi_tx_uv']!.put(_packMi(miTxUV, miRows, miCols, 5));
  drivers['mi_level_yv']!.put(_packMi(lvlYv, miRows, miCols, 6));
  drivers['mi_level_yh']!.put(_packMi(lvlYh, miRows, miCols, 6));
  drivers['mi_level_u']!.put(_packMi(lvlU, miRows, miCols, 6));
  drivers['mi_level_v']!.put(_packMi(lvlV, miRows, miCols, 6));
  drivers['mi_skip']!.put(_packMi(skip, miRows, miCols, 1));
  drivers['mi_is_inter']!.put(_packMi(isInter, miRows, miCols, 1));
  drivers['mi_block_w']!.put(_packMi(blockW, miRows, miCols, 8));
  drivers['mi_block_h']!.put(_packMi(blockH, miRows, miCols, 8));

  final rng = Random(seed);
  var totalChanged = 0;

  List<List<int>> randPlane(int w, int h, int mode) {
    final p = List.generate(h, (_) => List<int>.filled(w, 0));
    for (var y = 0; y < h; y++) {
      for (var x = 0; x < w; x++) {
        if (mode == 0) {
          p[y][x] = rng.nextInt(pxMax + 1);
        } else if (mode == 1) {
          // Plateaus scaled to the bd range so wide/flat kernels engage the
          // same way the 8-bit test does.
          final plateau = (100 + 6 * ((x ~/ 8) + (y ~/ 8))) << s;
          p[y][x] = (plateau + rng.nextInt(3) - 1).clamp(0, pxMax);
        } else {
          final grad = (60 + (x + y)) << s;
          p[y][x] = (grad + rng.nextInt(3) - 1).clamp(0, pxMax);
        }
      }
    }
    return p;
  }

  for (var iter = 0; iter < iters; iter++) {
    final mode = iter % 3;
    final py = randPlane(width, height, mode);
    final pu = numPlanes == 3 ? randPlane(cw, ch, mode) : <List<int>>[];
    final pv = numPlanes == 3 ? randPlane(cw, ch, mode) : <List<int>>[];

    drivers['frame']!.put(_packPlane(py, width, height, bd));
    if (numPlanes == 3) {
      drivers['frame_u']!.put(_packPlane(pu, cw, ch, bd));
      drivers['frame_v']!.put(_packPlane(pv, cw, ch, bd));
    }
    await clk.nextPosedge;

    // Golden: the captured deblocked planes for this iteration.
    List<List<int>> unflat(List<int> f, int w, int h) =>
        List.generate(h, (y) => f.sublist(y * w, y * w + w));
    final g = gold[iter];
    final gy = unflat(g.y, width, height);
    final gu = numPlanes == 3 ? unflat(g.u, cw, ch) : <List<int>>[];
    final gv = numPlanes == 3 ? unflat(g.v, cw, ch) : <List<int>>[];

    void checkPlane(
      String outPort,
      List<List<int>> gold,
      List<List<int>> src,
      int w,
      int h,
    ) {
      final val = dut.output(outPort).value;
      final got = List.generate(h, (y) => List<int>.filled(w, 0));
      for (var y = 0; y < h; y++) {
        for (var x = 0; x < w; x++) {
          got[y][x] = val
              .getRange((y * w + x) * bd, (y * w + x) * bd + bd)
              .toInt();
        }
      }
      for (var y = 0; y < h; y++) {
        expect(
          got[y],
          equals(gold[y]),
          reason: '$label $outPort iter=$iter row=$y\nin =${src[y]}',
        );
        for (var x = 0; x < w; x++) {
          if (gold[y][x] != src[y][x]) totalChanged++;
        }
      }
    }

    checkPlane('out', gy, py, width, height);
    if (numPlanes == 3) {
      checkPlane('out_u', gu, pu, cw, ch);
      checkPlane('out_v', gv, pv, cw, ch);
    }
  }

  if (expectChange) {
    expect(
      totalChanged,
      greaterThan(0),
      reason: '$label never modified any pixel',
    );
  } else {
    expect(
      totalChanged,
      equals(0),
      reason: '$label expected identity but pixels changed',
    );
  }
  await Simulator.endSimulation();
}

void main() {
  tearDown(() async {
    await Simulator.reset();
  });

  for (final bd in [10, 12]) {
    test('luma filter14 interior (32x32 TX_16X16) bd=$bd', () async {
      const w = 32, h = 32, mr = 8, mc = 8;
      await runCase(
        label: 'f14',
        bd: bd,
        width: w,
        height: h,
        numPlanes: 1,
        subX: 1,
        subY: 1,
        miTxY: _fill(mr, mc, 2), // TX_16X16
        miTxUV: _fill(mr, mc, 1),
        lvlYv: _fill(mr, mc, 40),
        lvlYh: _fill(mr, mc, 40),
        lvlU: _fill(mr, mc, 0),
        lvlV: _fill(mr, mc, 0),
        skip: _fill(mr, mc, 0),
        isInter: _fill(mr, mc, 0),
        blockW: _fill(mr, mc, 16),
        blockH: _fill(mr, mc, 16),
        sharpness: 0,
        iters: 4,
        seed: 0x140 + bd,
        gold: _gold[0x140 + bd]!,
      );
    });

    test('chroma filter6 4:2:0 (16x16 luma, 8x8 chroma) bd=$bd', () async {
      const w = 16, h = 16, mr = 4, mc = 4;
      await runCase(
        label: 'chroma6',
        bd: bd,
        width: w,
        height: h,
        numPlanes: 3,
        subX: 1,
        subY: 1,
        miTxY: _fill(mr, mc, 1),
        miTxUV: _fill(mr, mc, 1), // chroma TX_8X8 -> filter6
        lvlYv: _fill(mr, mc, 32),
        lvlYh: _fill(mr, mc, 32),
        lvlU: _fill(mr, mc, 28),
        lvlV: _fill(mr, mc, 24),
        skip: _fill(mr, mc, 0),
        isInter: _fill(mr, mc, 0),
        blockW: _fill(mr, mc, 16),
        blockH: _fill(mr, mc, 16),
        sharpness: 1,
        iters: 6,
        seed: 0xC00 + bd,
        gold: _gold[0xC00 + bd]!,
      );
    });

    test('chroma filter4 4:2:0 (chroma TX_4X4) bd=$bd', () async {
      const w = 16, h = 16, mr = 4, mc = 4;
      await runCase(
        label: 'chroma4',
        bd: bd,
        width: w,
        height: h,
        numPlanes: 3,
        subX: 1,
        subY: 1,
        miTxY: _fill(mr, mc, 0), // luma TX_4X4
        miTxUV: _fill(mr, mc, 0), // chroma TX_4X4 -> filter4
        lvlYv: _fill(mr, mc, 24),
        lvlYh: _fill(mr, mc, 24),
        lvlU: _fill(mr, mc, 30),
        lvlV: _fill(mr, mc, 30),
        skip: _fill(mr, mc, 0),
        isInter: _fill(mr, mc, 0),
        blockW: _fill(mr, mc, 8),
        blockH: _fill(mr, mc, 8),
        sharpness: 0,
        iters: 6,
        seed: 0xC40 + bd,
        gold: _gold[0xC40 + bd]!,
      );
    });
  }

  // Subsampling geometry: 4:4:4 (subX=0,subY=0) and 4:2:2 (subX=1,subY=0).
  // Exercised at bd=8 and bd=10.
  for (final bd in [8, 10]) {
    test('chroma 4:4:4 (subX=0,subY=0) bd=$bd', () async {
      const w = 16, h = 16, mr = 4, mc = 4;
      await runCase(
        label: '444',
        bd: bd,
        width: w,
        height: h,
        numPlanes: 3,
        subX: 0,
        subY: 0,
        miTxY: _fill(mr, mc, 1),
        miTxUV: _fill(mr, mc, 1), // chroma tx dim>0 -> filter6
        lvlYv: _fill(mr, mc, 32),
        lvlYh: _fill(mr, mc, 32),
        lvlU: _fill(mr, mc, 28),
        lvlV: _fill(mr, mc, 26),
        skip: _fill(mr, mc, 0),
        isInter: _fill(mr, mc, 0),
        blockW: _fill(mr, mc, 16),
        blockH: _fill(mr, mc, 16),
        sharpness: 1,
        iters: 6,
        seed: 0x444 + bd,
        gold: _gold[0x444 + bd]!,
      );
    });

    test('chroma 4:2:2 (subX=1,subY=0) bd=$bd', () async {
      const w = 16, h = 16, mr = 4, mc = 4;
      await runCase(
        label: '422',
        bd: bd,
        width: w,
        height: h,
        numPlanes: 3,
        subX: 1,
        subY: 0,
        miTxY: _fill(mr, mc, 1),
        miTxUV: _fill(mr, mc, 1),
        lvlYv: _fill(mr, mc, 30),
        lvlYh: _fill(mr, mc, 30),
        lvlU: _fill(mr, mc, 28),
        lvlV: _fill(mr, mc, 26),
        skip: _fill(mr, mc, 0),
        isInter: _fill(mr, mc, 0),
        blockW: _fill(mr, mc, 16),
        blockH: _fill(mr, mc, 16),
        sharpness: 0,
        iters: 6,
        seed: 0x422 + bd,
        gold: _gold[0x422 + bd]!,
      );
    });
  }
}
